<?php
namespace App\Http\Controllers;
use App\Models\{Ticket,TicketComment,AuditLog,User}; use Illuminate\Http\Request;
class TicketController extends Controller {
 public function index(Request $request){$user=$request->user();$q=$user->isStaff()?Ticket::query():Ticket::where('user_id',$user->id);if($request->filled('status'))$q->where('status',$request->status);if($request->filled('search'))$q->where(fn($x)=>$x->where('title','like','%'.$request->search.'%')->orWhere('description','like','%'.$request->search.'%'));return view('tickets.index',['tickets'=>$q->with(['requester','assignee'])->latest()->paginate(12)->withQueryString()]);}
 public function create(){return view('tickets.create');}
 public function store(Request $request){$data=$request->validate(['title'=>'required|string|max:180','description'=>'required|string|min:10','priority'=>'required|in:low,normal,high,urgent','category'=>'required|string|max:80']);$ticket=Ticket::create($data+['user_id'=>$request->user()->id]);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'ticket.created','auditable_type'=>Ticket::class,'auditable_id'=>$ticket->id,'ip_address'=>$request->ip()]);return redirect()->route('tickets.show',$ticket)->with('success','Ticket créé avec succès.');}
 public function show(Ticket $ticket){$this->authorizeTicket($ticket);$ticket->load(['requester','assignee','comments.user','auditLogs.user']);return view('tickets.show',compact('ticket'));}
 public function edit(Ticket $ticket){abort_unless(request()->user()->isStaff(),403);return view('tickets.edit',['ticket'=>$ticket,'technicians'=>User::whereIn('role',['admin','technician'])->orderBy('name')->get()]);}
 public function update(Request $request,Ticket $ticket){abort_unless($request->user()->isStaff(),403);$data=$request->validate(['status'=>'required|in:open,in_progress,pending,resolved,closed','priority'=>'required|in:low,normal,high,urgent','assigned_to'=>'nullable|exists:users,id']);$data['resolved_at']=in_array($data['status'],['resolved','closed'])?now():null;$ticket->update($data);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'ticket.updated','auditable_type'=>Ticket::class,'auditable_id'=>$ticket->id,'metadata'=>$data,'ip_address'=>$request->ip()]);return redirect()->route('tickets.show',$ticket)->with('success','Ticket mis à jour.');}
 public function comment(Request $request,Ticket $ticket){$this->authorizeTicket($ticket);$data=$request->validate(['body'=>'required|string|max:5000']);TicketComment::create(['ticket_id'=>$ticket->id,'user_id'=>$request->user()->id,'body'=>$data['body']]);return back()->with('success','Commentaire ajouté.');}
 private function authorizeTicket(Ticket $ticket):void{abort_unless(request()->user()->isStaff()||$ticket->user_id===request()->user()->id,403);}
}
